<?php
namespace App\Filament\Admin\Resources\PolicyTransactions\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\PolicyTransactions\PolicyTransactionResource;use Filament\Actions\Action;use Filament\Forms\Components\{Select,TextInput,Textarea};use Filament\Resources\Pages\ViewRecord;use Illuminate\Support\Str;final class ViewPolicyTransaction extends ViewRecord{protected static string $resource=PolicyTransactionResource::class;protected function getHeaderActions():array{return[Action::make('requestPayment')->label('Request payment')->icon('heroicon-o-wallet')->visible(fn()=>$this->record->status==='PAYMENT_PENDING'&&!$this->record->payment_intent_id)->fillForm(fn()=>['idempotency_key'=>(string)Str::uuid()])->schema([Select::make('provider')->options(['maviance'=>'Maviance','campay'=>'Campay','mtn_momo'=>'MTN MoMo','orange_money'=>'Orange Money'])->required()->native(false),TextInput::make('payer_phone_e164')->tel()->required()->maxLength(20),TextInput::make('idempotency_key')->required()->maxLength(128)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyServicingService::class)->requestPayment($this->record,$d,auth()->user()))===null)return;}),Action::make('confirmPayment')->label('Validate reconciled payment')->icon('heroicon-o-banknotes')->visible(fn()=>$this->record->status==='PAYMENT_PENDING'&&$this->record->payment_intent_id)->action(function(){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyServicingService::class)->linkPayment($this->record,$this->record->payment))===null)return;}),Action::make('approve')->icon('heroicon-o-check-circle')->color('success')->requiresConfirmation()->visible(fn()=>$this->record->status==='PENDING_APPROVAL')->action(function(){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyServicingService::class)->approve($this->record,auth()->user()))===null)return;}),Action::make('reject')->icon('heroicon-o-x-circle')->color('danger')->visible(fn()=>in_array($this->record->status,['PAYMENT_PENDING','PENDING_APPROVAL'],true))->schema([Textarea::make('reason')->required()->minLength(20)->maxLength(2000)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyServicingService::class)->reject($this->record,$d['reason'],auth()->user()))===null)return;})];}}
